import{f as t,o as i,c as s,a6 as o}from"./chunks/framework.Dd1qhYRL.js";const m=JSON.parse('{"title":"noorm settings edit","description":"","frontmatter":{},"headers":[],"relativePath":"cli/settings-edit.md","filePath":"cli/settings-edit.md"}'),n={name:"cli/settings-edit.md"};function a(d,e,r,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="noorm-settings-edit" tabindex="-1">noorm settings edit <a class="header-anchor" href="#noorm-settings-edit" aria-label="Permalink to “noorm settings edit”">​</a></h1><p>Edit <code>.noorm/settings.yml</code> from a menu instead of by hand.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span></span></code></pre></div><p>The menu offers Paths, Build, Strict, Logging, Stages, Rules, Teardown, and Done. Each section saves as soon as its prompts finish. Cancelling inside a section drops that section&#39;s edit and returns to the menu. Done, or a cancel at the menu, exits 0 with <code>Settings saved.</code></p><h2 id="where-does-it-refuse-to-run" tabindex="-1">Where does it refuse to run? <a class="header-anchor" href="#where-does-it-refuse-to-run" aria-label="Permalink to “Where does it refuse to run?”">​</a></h2><p>It needs a terminal. <code>settings.yml</code> is plain YAML, so a script edits the file itself.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><code>--yes</code>, <code>-y</code>, or <code>NOORM_YES=1</code></td><td><code>Error: noorm settings edit is interactive only.</code> Edit <code>settings.yml</code> directly, then run <code>noorm settings build</code> to validate. Exit 2</td></tr><tr><td>No terminal on stdin</td><td><code>Error: noorm settings edit requires an interactive terminal.</code>, exit 2</td></tr><tr><td>No <code>settings.yml</code></td><td><code>Error: No settings.yml found. Run: noorm settings init</code>, exit 2</td></tr><tr><td><code>settings.yml</code> does not load</td><td><code>Error: Failed to load settings: …</code>, exit 1</td></tr></tbody></table><p><code>--yes</code> is the only flag, and it exists for the redirect above. See <a href="/guide/automation/non-interactive.html">non-interactive operation</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/cli/settings-secret.html"><code>noorm settings secret</code></a>: declare required secrets per stage</li><li><a href="/guide/environments/stages.html">Stages</a></li></ul>',10)])])}const p=t(n,[["render",a]]);export{m as __pageData,p as default};
